// Generated by LCD Wizard - LVGL filesystem driver backed by SPIFFS

#include "ui_fs.h"
#include <FS.h>
#include <SPIFFS.h>

#define UI_FS       SPIFFS
#define UI_FS_LETTER 'S'

static void * ui_fs_open(lv_fs_drv_t * drv, const char * path, lv_fs_mode_t mode)
{
    (void)drv;
    if (mode != LV_FS_MODE_RD) return NULL;   // assets are read-only
    File f = UI_FS.open(path, FILE_READ);
    if (!f || f.isDirectory()) return NULL;
    return (void *)(new File(f));
}

static lv_fs_res_t ui_fs_close(lv_fs_drv_t * drv, void * file_p)
{
    (void)drv;
    File * fp = (File *)file_p;
    fp->close();
    delete fp;
    return LV_FS_RES_OK;
}

static lv_fs_res_t ui_fs_read(lv_fs_drv_t * drv, void * file_p, void * buf, uint32_t btr, uint32_t * br)
{
    (void)drv;
    File * fp = (File *)file_p;
    *br = fp->read((uint8_t *)buf, btr);
    return LV_FS_RES_OK;
}

static lv_fs_res_t ui_fs_seek(lv_fs_drv_t * drv, void * file_p, uint32_t pos, lv_fs_whence_t whence)
{
    (void)drv;
    File * fp = (File *)file_p;
    SeekMode m = SeekSet;
    if (whence == LV_FS_SEEK_CUR) m = SeekCur;
    else if (whence == LV_FS_SEEK_END) m = SeekEnd;
    return fp->seek(pos, m) ? LV_FS_RES_OK : LV_FS_RES_UNKNOWN;
}

static lv_fs_res_t ui_fs_tell(lv_fs_drv_t * drv, void * file_p, uint32_t * pos_p)
{
    (void)drv;
    *pos_p = ((File *)file_p)->position();
    return LV_FS_RES_OK;
}

bool ui_fs_exists(const char * path)
{
    return UI_FS.exists(path);
}

bool ui_fs_init(void)
{
    if (!UI_FS.begin(true)) {   // true = format if the mount fails
        Serial.println("SPIFFS: mount failed");
        return false;
    }
    Serial.printf("SPIFFS mounted: %u / %u bytes used\n",
                  (unsigned)UI_FS.usedBytes(), (unsigned)UI_FS.totalBytes());

    static lv_fs_drv_t drv;
    lv_fs_drv_init(&drv);
    drv.letter   = UI_FS_LETTER;
    drv.open_cb  = ui_fs_open;
    drv.close_cb = ui_fs_close;
    drv.read_cb  = ui_fs_read;
    drv.seek_cb  = ui_fs_seek;
    drv.tell_cb  = ui_fs_tell;
    lv_fs_drv_register(&drv);

    // Warn early rather than showing empty image placeholders on screen.
    if (!UI_FS.exists("/dovora_simplistic_day_partial_cloud_96.bin")) Serial.println("missing asset: /dovora_simplistic_day_partial_cloud_96.bin");
    if (!UI_FS.exists("/overcast.bin")) Serial.println("missing asset: /overcast.bin");
    if (!UI_FS.exists("/overcast_2.bin")) Serial.println("missing asset: /overcast_2.bin");
    if (!UI_FS.exists("/day_clear.bin")) Serial.println("missing asset: /day_clear.bin");
    if (!UI_FS.exists("/day_partial_cloud.bin")) Serial.println("missing asset: /day_partial_cloud.bin");
    if (!UI_FS.exists("/rain.bin")) Serial.println("missing asset: /rain.bin");
    if (!UI_FS.exists("/cloudy.bin")) Serial.println("missing asset: /cloudy.bin");
    if (!UI_FS.exists("/snow.bin")) Serial.println("missing asset: /snow.bin");
    if (!UI_FS.exists("/rain_2.bin")) Serial.println("missing asset: /rain_2.bin");
    if (!UI_FS.exists("/partly_cloudy.bin")) Serial.println("missing asset: /partly_cloudy.bin");
    if (!UI_FS.exists("/clear.bin")) Serial.println("missing asset: /clear.bin");
    if (!UI_FS.exists("/snow_2.bin")) Serial.println("missing asset: /snow_2.bin");
    if (!UI_FS.exists("/fog.bin")) Serial.println("missing asset: /fog.bin");
    if (!UI_FS.exists("/partly_cloudy_main_96x96.bin")) Serial.println("missing asset: /partly_cloudy_main_96x96.bin");
    if (!UI_FS.exists("/partly_cloudy_96x96_tr.bin")) Serial.println("missing asset: /partly_cloudy_96x96_tr.bin");

    return true;
}
